import{_ as i,C as r,o as t,c,a3 as a,b as l,w as o,a as s,E as n,a4 as h}from"./chunks/framework.DACwFHq9.js";const B=JSON.parse('{"title":"系统 WebView 免费能力调查记录","description":"","frontmatter":{},"headers":[],"relativePath":"design/system-webview-free-capabilities-investigation.md","filePath":"design/system-webview-free-capabilities-investigation.md","lastUpdated":1786377181000}'),p={name:"design/system-webview-free-capabilities-investigation.md"};function b(u,e,E,A,g,f){const d=r("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a(`<h1 id="系统-webview-免费能力调查记录" tabindex="-1">系统 WebView 免费能力调查记录 <a class="header-anchor" href="#系统-webview-免费能力调查记录" aria-label="Permalink to &quot;系统 WebView 免费能力调查记录&quot;">​</a></h1><blockquote><p>调查日期：2026-08-10<br> 状态：已完成真实 Windows Tauri WebView2 探针；部分模型下载能力仍为实验性结论。</p></blockquote><h2 id="_1-调查目的" tabindex="-1">1. 调查目的 <a class="header-anchor" href="#_1-调查目的" aria-label="Permalink to &quot;1. 调查目的&quot;">​</a></h2><p>评估 AIO Hub 是否能复用系统浏览器 / 系统 WebView 提供的免费能力，从而减少用户配置翻译模型、云端 API Key 或额外服务的成本。</p><p>本记录只描述已在当前开发机真实 Tauri WebView 中验证的结果，不把“浏览器存在某个 API”直接等同于“产品中可稳定交付”。</p><h2 id="_2-当前浏览器表面与边界" tabindex="-1">2. 当前浏览器表面与边界 <a class="header-anchor" href="#_2-当前浏览器表面与边界" aria-label="Permalink to &quot;2. 当前浏览器表面与边界&quot;">​</a></h2><p>项目中需要区分三种不同的表面：</p><table tabindex="0"><thead><tr><th>表面</th><th>当前实现</th><th>能否直接调用外部浏览器翻译 UI</th></tr></thead><tbody><tr><td>AIO Hub 主窗口</td><td>Tauri 系统 WebView；Windows 为 WebView2</td><td>否</td></tr><tr><td>网页蒸馏室交互页</td><td>本地代理后的 sandbox iframe，并注入桥接脚本</td><td>否</td></tr><tr><td>“在系统浏览器中打开”</td><td>Tauri opener 将 URL 交给默认浏览器</td><td>否，仅能打开 URL</td></tr></tbody></table><p>主窗口由 <a href="./../../src-tauri/src/lib.rs"><code>src-tauri/src/lib.rs</code></a> 创建。网页蒸馏室的交互页面由 <a href="../../src/tools/web-distillery/core/iframe-bridge.ts"><code>src/tools/web-distillery/core/iframe-bridge.ts</code></a> 创建 iframe 并加载本地代理 URL；工具栏“在系统浏览器中打开”使用 <a href="./../../src/tools/web-distillery/components/interactive/InteractiveToolbar.vue"><code>src/tools/web-distillery/components/interactive/InteractiveToolbar.vue</code></a> 中的 opener。</p><p>因此，AIO Hub 不能可靠地调用 Edge/Chrome 地址栏里的翻译菜单，也不能读取外部浏览器翻译后的 DOM、Cookie、密码或扩展状态。可以评估的是<strong>应用自身 WebView 和操作系统公开暴露的能力</strong>。</p><h2 id="_3-测试环境与方法" tabindex="-1">3. 测试环境与方法 <a class="header-anchor" href="#_3-测试环境与方法" aria-label="Permalink to &quot;3. 测试环境与方法&quot;">​</a></h2><h3 id="_3-1-环境" tabindex="-1">3.1 环境 <a class="header-anchor" href="#_3-1-环境" aria-label="Permalink to &quot;3.1 环境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>实测值</th></tr></thead><tbody><tr><td>平台</td><td>Windows 10 专业工作站版 x64</td></tr><tr><td>WebView Runtime</td><td>Microsoft Edge WebView2 Runtime <code>151.0.4129.72</code></td></tr><tr><td>应用运行方式</td><td>已编译的 Tauri debug 二进制 + WebdriverIO Tauri E2E</td></tr><tr><td>页面上下文</td><td><code>http://localhost:&lt;port&gt;/</code>，<code>isSecureContext === true</code></td></tr><tr><td>WebView User-Agent（源码默认）</td><td>固定为 Chrome <code>122.0.0.0</code></td></tr></tbody></table><p>探针使用项目现有 <a href="../../tests/tauri-e2e/wdio.conf.ts"><code>tests/tauri-e2e/wdio.conf.ts</code></a> 启动真实 Tauri 窗口并通过 WebDriver 在 WebView 内执行 JavaScript。所有模型下载尝试都使用隔离的 E2E 用户数据目录，测试完成后清理。</p><h3 id="_3-2-user-agent-对照" tabindex="-1">3.2 User-Agent 对照 <a class="header-anchor" href="#_3-2-user-agent-对照" aria-label="Permalink to &quot;3.2 User-Agent 对照&quot;">​</a></h3><p><a href="./../../src-tauri/src/lib.rs"><code>src-tauri/src/lib.rs</code></a> 为页面设置了固定 UA。为了排除它对内建 AI API 的影响，曾临时把 Chrome <code>122.0.0.0</code> 改为 <code>151.0.0.0</code>、重新构建、重跑探针，随后恢复源码并按原始源码重新构建 debug 二进制。</p><p>结果：Translator 的语言对可用性没有变化，仍全部为 <code>unavailable</code>。因此当前结论中，固定 UA <strong>不是</strong> Translator 不可用的充分解释。</p><h2 id="_4-实测结果" tabindex="-1">4. 实测结果 <a class="header-anchor" href="#_4-实测结果" aria-label="Permalink to &quot;4. 实测结果&quot;">​</a></h2><h3 id="_4-1-翻译与语言能力" tabindex="-1">4.1 翻译与语言能力 <a class="header-anchor" href="#_4-1-翻译与语言能力" aria-label="Permalink to &quot;4.1 翻译与语言能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>API 表面</th><th>可用性实测</th><th>结论</th></tr></thead><tbody><tr><td><code>Translator</code></td><td><code>function</code></td><td><code>en→zh</code>、<code>zh→en</code>、<code>en→ja</code>、<code>ja→en</code>、<code>en→es</code>、<code>es→en</code>、<code>en→fr</code>、<code>de→en</code> 均为 <code>unavailable</code></td><td>不可作为默认本地翻译后端</td></tr><tr><td><code>LanguageDetector</code></td><td><code>function</code></td><td><code>availability()</code> 为 <code>downloadable</code></td><td>仅实验性候选</td></tr><tr><td><code>Summarizer</code></td><td><code>function</code></td><td><code>availability()</code> 为 <code>downloadable</code></td><td>可进一步做受控 PoC</td></tr><tr><td><code>Writer</code> / <code>Rewriter</code> / <code>Proofreader</code> / <code>LanguageModel</code></td><td><code>undefined</code></td><td>无可用入口</td><td>不可依赖</td></tr></tbody></table><h4 id="translator-结论" tabindex="-1">Translator 结论 <a class="header-anchor" href="#translator-结论" aria-label="Permalink to &quot;Translator 结论&quot;">​</a></h4><p>虽然 WebView2 暴露了 <code>Translator</code>，但当前运行环境中的常用语言对均无法创建本地模型。因此不能把它接入为“无配置、免费翻译”的默认实现，也不能在 UI 中仅依据 <code>typeof Translator === &quot;function&quot;</code> 展示可用入口。</p><p>正确的运行时策略应为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Translator API 存在</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Translator.availability({ sourceLanguage, targetLanguage })</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>仅 available / downloadable（且完成可控下载）才可进入本地翻译路径</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>否则继续使用已配置 LLM、本地模型或明确的可选 Provider</span></span></code></pre></div><h4 id="languagedetector-下载测试" tabindex="-1">LanguageDetector 下载测试 <a class="header-anchor" href="#languagedetector-下载测试" aria-label="Permalink to &quot;LanguageDetector 下载测试&quot;">​</a></h4><p>对 <code>LanguageDetector.create()</code> 做了真实模型创建与中英文日文识别测试：</p><ol><li><code>availability()</code> 初始返回 <code>downloadable</code>；</li><li>在 WebView 页面中后台启动 <code>create()</code>；</li><li>以 5 秒间隔轮询；</li><li>最长等待 5 分钟；</li><li>未进入完成或明确错误状态。</li></ol><p>这表示 <code>downloadable</code> 不能视为当前机器上立即可交付：可能是 WebView2 模型下载通道、网络、隔离用户目录、模型服务初始化或缺少进度回调导致。产品若继续验证，必须有下载进度、超时、取消和明确降级提示，且不得阻塞普通翻译流程。</p><h3 id="_4-2-文字朗读-tts" tabindex="-1">4.2 文字朗读（TTS） <a class="header-anchor" href="#_4-2-文字朗读-tts" aria-label="Permalink to &quot;4.2 文字朗读（TTS）&quot;">​</a></h3><p>真实 WebView 探针结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typeof speechSynthesis === &quot;object&quot;</span></span>
<span class="line"><span>首次 getVoices() 数量：0</span></span>
<span class="line"><span>等待 voiceschanged / 异步加载后：10</span></span></code></pre></div><p>检测到的本地语音包括：</p><ul><li><code>Microsoft Huihui</code>（zh-CN）</li><li><code>Microsoft Kangkang</code>（zh-CN）</li><li><code>Microsoft Yaoyao</code>（zh-CN）</li><li><code>Microsoft Mark</code>、<code>Microsoft Zira</code>、<code>Microsoft David</code>（en-US）</li><li><code>Microsoft Ayumi</code>、<code>Microsoft Haruka</code>、<code>Microsoft Ichiro</code>、<code>Microsoft Sayaka</code>（ja-JP）</li></ul><p>另外，使用 Windows SAPI (<code>System.Speech.Synthesis.SpeechSynthesizer</code>) 导出 WAV 对系统声库进行了人工试听验证：</p><ul><li><code>Microsoft Huihui</code> 为可信的中文偏女声；</li><li><code>Microsoft David</code> 为可信的英文男声；</li><li><code>Microsoft Kangkang</code> 的声库元数据标记为男性，但导出的音频与 <code>Microsoft Yaoyao</code> 曾逐字节相同，实际听感也偏女声。</li></ul><p><strong>不要依据系统声库的 <code>Gender</code> 元数据直接在产品 UI 标注“男声”或“女声”。</strong> 应按实际试听、运行时声音特征或保守的“语音名称”展示。SAPI 导出的声音与 WebView <code>speechSynthesis</code> 实际播放也可能不完全一致，正式接入仍需要真实播放验证。</p><p>TTS 是当前最适合优先接入的零 API Key 能力，可用于：</p><ul><li>聊天消息和翻译结果朗读；</li><li>OCR 识别结果朗读；</li><li>网页蒸馏室摘要朗读；</li><li>外语学习和字幕辅助。</li></ul><h3 id="_4-3-其他-webview-api-表面" tabindex="-1">4.3 其他 WebView API 表面 <a class="header-anchor" href="#_4-3-其他-webview-api-表面" aria-label="Permalink to &quot;4.3 其他 WebView API 表面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>实测值</th><th>建议</th></tr></thead><tbody><tr><td><code>webkitSpeechRecognition</code></td><td><code>function</code></td><td>需要单独验证麦克风权限、离线性、联网依赖和跨平台表现；不可承诺免费离线</td></tr><tr><td><code>spellcheck</code></td><td>textarea 属性可用</td><td>可用于聊天、翻译和富文本输入框；需按词典缺失优雅降级</td></tr><tr><td><code>EyeDropper</code></td><td><code>function</code></td><td>可简化取色类工具</td></tr><tr><td><code>IdleDetector</code></td><td><code>function</code></td><td>有权限和隐私语义，不能静默启用</td></tr><tr><td><code>CompressionStream</code> / <code>DecompressionStream</code></td><td><code>function</code></td><td>可用于本地导入导出或压缩辅助</td></tr><tr><td><code>showOpenFilePicker</code> / <code>showSaveFilePicker</code></td><td><code>function</code></td><td>项目已有 Tauri 原生文件能力，优先复用项目封装</td></tr><tr><td><code>BarcodeDetector</code></td><td><code>undefined</code></td><td>不可依赖浏览器原生实现</td></tr></tbody></table><h3 id="_4-4-浏览器扩展与宿主-api" tabindex="-1">4.4 浏览器扩展与宿主 API <a class="header-anchor" href="#_4-4-浏览器扩展与宿主-api" aria-label="Permalink to &quot;4.4 浏览器扩展与宿主 API&quot;">​</a></h3><p>页面中存在 <code>chrome.webview</code>，这是 WebView2 宿主通信对象，不代表 Chrome/Edge 浏览器扩展已安装或可用。</p><p>当前项目未在窗口构建中调用 <code>browser_extensions_enabled(true)</code>，也未配置扩展路径。即使后续启用，扩展也不是跨平台统一能力，并且网页蒸馏室使用本地代理 URL，普通针对原始站点匹配的内容脚本不一定直接生效。</p><p>浏览器扩展不应作为当前“免费翻译”方案的首选。</p><h2 id="_5-产品决策建议" tabindex="-1">5. 产品决策建议 <a class="header-anchor" href="#_5-产品决策建议" aria-label="Permalink to &quot;5. 产品决策建议&quot;">​</a></h2><h3 id="_5-1-可直接推进" tabindex="-1">5.1 可直接推进 <a class="header-anchor" href="#_5-1-可直接推进" aria-label="Permalink to &quot;5.1 可直接推进&quot;">​</a></h3><ol><li>建立统一的 <code>platform-capabilities</code> / <code>local-capabilities</code> 探测层。</li><li>在初始化后异步加载系统声音列表，使用 <code>voiceschanged</code> 处理延迟加载。</li><li>将 TTS 接入聊天、翻译、OCR 和网页摘要的朗读入口。</li><li>对编辑器和输入框启用 <code>spellcheck</code>，但不承诺词典覆盖。</li><li>继续优先复用已有 Windows OCR 和 Tesseract 路径。</li></ol><h3 id="_5-2-仅作为实验性功能" tabindex="-1">5.2 仅作为实验性功能 <a class="header-anchor" href="#_5-2-仅作为实验性功能" aria-label="Permalink to &quot;5.2 仅作为实验性功能&quot;">​</a></h3><ol><li>LanguageDetector：仅在用户主动启用或诊断页中尝试模型下载；必须具备超时、取消和回退。</li><li>Summarizer：先做短文本、可取消、可观察下载进度的 PoC；不可替代现有 LLM 摘要链路。</li><li>Speech Recognition：先验证权限、网络和隐私语义，再决定是否暴露给普通用户。</li></ol><h3 id="_5-3-暂不作为默认依赖" tabindex="-1">5.3 暂不作为默认依赖 <a class="header-anchor" href="#_5-3-暂不作为默认依赖" aria-label="Permalink to &quot;5.3 暂不作为默认依赖&quot;">​</a></h3><ol><li>WebView <code>Translator</code> 本地翻译；</li><li>外部 Edge/Chrome 翻译菜单；</li><li>用户 Edge 配置文件、密码、Cookie 或扩展；</li><li>不受控的公共免费翻译站点接口；</li><li>仅根据系统声库 Gender 元数据选择“男声”。</li></ol><h2 id="_6-推荐能力选择链" tabindex="-1">6. 推荐能力选择链 <a class="header-anchor" href="#_6-推荐能力选择链" aria-label="Permalink to &quot;6. 推荐能力选择链&quot;">​</a></h2>`,52)),(t(),l(h,null,{default:o(()=>[n(d,{id:"mermaid-559",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E5%8A%9F%E8%83%BD%E8%AF%B7%E6%B1%82%5D%20--%3E%20B%7B%E6%98%AF%E5%90%A6%E6%9C%89%E5%8F%AF%E9%AA%8C%E8%AF%81%E7%9A%84%E6%9C%AC%E5%9C%B0%E8%83%BD%E5%8A%9B%3F%7D%0A%20%20%20%20B%20--%3E%7CTTS%20%2F%20%E6%8B%BC%E5%86%99%E6%A3%80%E6%9F%A5%20%2F%20OCR%7C%20C%5B%E7%9B%B4%E6%8E%A5%E4%BD%BF%E7%94%A8%E7%B3%BB%E7%BB%9F%E6%88%96%E9%A1%B9%E7%9B%AE%E6%9C%AC%E5%9C%B0%E5%AE%9E%E7%8E%B0%5D%0A%20%20%20%20B%20--%3E%7CLanguageDetector%20%2F%20Summarizer%7C%20D%7B%E6%A8%A1%E5%9E%8B%E5%B7%B2%E5%8F%AF%E7%94%A8%E4%B8%94%E5%81%A5%E5%BA%B7%3F%7D%0A%20%20%20%20D%20--%3E%7C%E6%98%AF%7C%20E%5B%E6%9C%AC%E5%9C%B0%E6%A8%A1%E5%9E%8B%E6%89%A7%E8%A1%8C%5D%0A%20%20%20%20D%20--%3E%7C%E5%90%A6%7C%20F%5B%E6%98%BE%E7%A4%BA%E5%8F%AF%E9%80%89%E4%B8%8B%E8%BD%BD%E6%88%96%E9%99%8D%E7%BA%A7%5D%0A%20%20%20%20B%20--%3E%7C%E7%BF%BB%E8%AF%91%7C%20G%7BTranslator%20%E5%AF%B9%E8%AF%AD%E8%A8%80%E5%AF%B9%E4%B8%BA%20available%3F%7D%0A%20%20%20%20G%20--%3E%7C%E5%90%A6%7C%20H%5B%E5%B7%B2%E9%85%8D%E7%BD%AE%20LLM%20%2F%20%E6%9C%AC%E5%9C%B0%E6%A8%A1%E5%9E%8B%20%2F%20%E6%98%BE%E5%BC%8F%20Provider%5D%0A%20%20%20%20G%20--%3E%7C%E6%98%AF%7C%20I%5B%E6%9C%AC%E5%9C%B0%E7%BF%BB%E8%AF%91%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="_7-后续验证清单" tabindex="-1">7. 后续验证清单 <a class="header-anchor" href="#_7-后续验证清单" aria-label="Permalink to &quot;7. 后续验证清单&quot;">​</a></h2><ul><li>[ ] 为 TTS 增加真实 WebView 播放测试，而不只验证声音列表和 SAPI 文件导出。</li><li>[ ] 验证 <code>speechSynthesis</code> 的不同声库在 WebView 与 SAPI 导出之间是否一致。</li><li>[ ] 为 LanguageDetector / Summarizer 记录下载事件、网络请求、错误和落盘位置，定位 5 分钟未完成的原因。</li><li>[ ] 在普通持久化用户目录与 E2E 隔离目录分别验证模型下载行为。</li><li>[ ] 为本地能力探测建立缓存、健康状态和用户可见的隐私说明。</li><li>[ ] 对网页蒸馏室实现“选中文本/摘要翻译”前，先定义 DOM 保留、缓存、撤销与动态页面增量更新策略。</li></ul>',2))])}const _=i(p,[["render",b]]);export{B as __pageData,_ as default};
